package ru.ratunov.bukvar.nativeapp;
import java.util.*;

/** Introductory adaptation, not a reproduction of the entire 1955 primer. */
public final class Course {
 public static final class Task {
  public final String kind, text, hint, meaning; public final String[] syllables;
  Task(String k,String t,String h,String m,String[] s){kind=k;text=t;hint=h;meaning=m;syllables=s;}
 }
 public static final class Lesson {
  public final String title, subtitle, letters; public final List<Task> tasks;
  Lesson(String t,String s,String l,Task... a){title=t;subtitle=s;letters=l;tasks=Collections.unmodifiableList(Arrays.asList(a));}
 }
 static Task talk(String t,String h){return new Task("talk",t,h,"",null);}
 static Task sound(String t,String h){return new Task("sound",t,h,"",null);}
 static Task blend(String t,String h){return new Task("blend",t,h,"",null);}
 static Task build(String t){return new Task("build",t,"Произнесите слово. Пусть ребёнок подберёт буквы по порядку, а затем прочитает получившееся.","",null);}
 public static Task read(String t,String s,String m){return new Task("read",t,"Сначала ребёнок читает сам. При затруднении помогите соединить звуки, затем предложите прочитать целиком.",m,s==null?null:s.split("\\|"));}
 public static final List<Lesson> LESSONS=Collections.unmodifiableList(Arrays.asList(
  new Lesson("А · У","Слушаем и произносим","ау",talk("Как зовут друг друга в лесу?","Произнесите «ау». Выделите голосом сначала [а], затем [у]."),sound("а","Скажите «а-а-а». Послушайте и повторите. Покажите А и а."),sound("у","Скажите «у-у-у». Сравните на слух с [а]. Покажите У и у."),build("ау"),blend("ау","Прочитайте последовательно [а], [у]. Здесь два гласных звука."),build("уа")),
  new Lesson("М · мама","Первый слог и слово","м",talk("Скажи «мама». Сколько частей слышишь?","Произнесите «ма-ма». Затем выделите первый звук: «ммма»."),sound("м","Потяните [м] без гласного: не «эм» и не «мэ»."),blend("ма","Тяните [м] и плавно переходите к [а]: м-м-ма. Не называйте буквы."),build("мама"),read("мама","ма|ма","Как ты ласково зовёшь маму?")),
  new Lesson("Ш · Маша","Новый звук в знакомых слогах","ш",talk("Скажи «шум». Какой звук первый?","Выделите [ш] протяжно, затем покажите Ш и ш."),sound("ш","Произнесите [ш] протяжно, без добавленного гласного."),blend("ша","Соедините [ш] и [а] без остановки."),build("Маша"),read("Маша","Ма|ша","Как зовут девочку?"),read("шум",null,"Что дома может шуметь?")),
  new Lesson("Р · рама","Слоги ра и ру","р",sound("р","Скажите «рама» и выделите первый звук. Не требуйте силой исправлять артикуляцию."),blend("ра","Соедините звуки, не называя букву «эр»."),build("рама"),read("рама","ра|ма","У чего бывает рама?"),read("Шура","Шу|ра","Повтори имя, которое прочитал."),read("ура","у|ра","Когда говорят «ура»?")),
  new Lesson("Л · Луша","Читаем короткую строку","л",sound("л","Произнесите «лампа» и выделите первый звук. Всё слово пока не задавайте читать."),blend("ла","Плавно прочитайте слог «ла»."),build("Луша"),read("Луша","Лу|ша","Как зовут девочку?"),read("мала","ма|ла","Что значит «мала»?"),read("Луша мала.",null,"О ком прочитал? Что о ней сказано?")),
  new Lesson("Ы · мыла","Сравниваем ма и мы","ы",sound("ы","Скажите «мы» и выделите второй звук. Покажите букву ы."),blend("мы","Прочитайте «ма», затем «мы». Обратите внимание на гласный."),build("шары"),read("шары","ша|ры","Какие бывают шары?"),read("мыла","мы|ла","Что мама мыла?"),read("Мама мыла раму.",null,"Кто мыл? Что мыли?")),
  new Lesson("С · Саша","Новый звук с","с",sound("с","Скажите «сыр». Выделите первый звук, не название «эс»."),blend("са","Плавно соедините [с] с [а]."),build("Саша"),read("Саша","Са|ша","Какое имя получилось?"),read("усы","у|сы","У кого бывают усы?"),read("Саша мыла раму.",null,"Кто мыл раму?")),
  new Lesson("Н · луна","Составляем новые слова","н",sound("н","Скажите «нос», выделите первый звук. Букву о будем читать дальше."),blend("на","Прочитайте «на», не называя букву «эн»."),build("луна"),read("луна","лу|на","Когда ты видел луну?"),read("наша","на|ша","Придумай устно фразу со словом «наша»."),read("Наша мама.",null,"Про кого написана строка?")),
  new Lesson("О · нос","Слова и предложения","о",sound("о","Скажите «осы» с ударением на первом звуке. Выделите [о] и покажите О и о."),blend("но","Прочитайте «на», затем «но». Какой гласный изменился?"),build("нос"),read("нос",null,"Для чего нужен нос?"),read("сом",null,"Сом — это рыба. Что ты о ней знаешь?"),read("сон",null,"Чем отличаются слова «сом» и «сон»?"),read("У нас сом.",null,"Какая рыба у нас?"))
 ));
 public static int size(){int n=0;for(Lesson l:LESSONS)n+=l.tasks.size();return n;}
}
